  Hypothesis MEMCPY : asan_memcpy_stmt.
  Variables (tbp tep srp cbp src b : Z) (es : list mbe) (insz n x lo shi : Z) (bs : list byte).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : mem).
  Hypothesis MID : AMBmid m0 b es insz n x.
  Hypothesis OK : mb_ok es insz.
  Hypothesis N1 : 1 <= n.
  Hypothesis NB : insz + n <= 2^30.
  Hypothesis TB : rw_cells asegs m0 tbp [C8 (wz srp); C8 (wz (mb_mid_out b es insz x))].
  Hypothesis TE : rw_cells asegs m0 tep [C8 (wz srp); C8 (wz (b + 8))].
  Hypothesis SR : rw_cells asegs m0 srp (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)).
  Hypothesis CBC : rw_cells asegs m0 cbp [C8 (wz src); C8 (wz n)].
  Hypothesis SRC : bytes_at asegs m0 src bs.
  Hypothesis LBS : zlength bs = n.
  Hypothesis SLO : src + n <= lo \/ bv_unsigned sp <= src.
  Hypothesis A1 : tbp + 16 <= lo \/ bv_unsigned sp <= tbp.
  Hypothesis A2 : tep + 16 <= lo \/ bv_unsigned sp <= tep.
  Hypothesis A3 : srp + 40 <= lo \/ bv_unsigned sp <= srp.
  Hypothesis A4 : cbp + 16 <= lo \/ bv_unsigned sp <= cbp.
  Hypothesis B0 : mb_off b (mb_put_es es insz n x) src n.
  Hypothesis B1 : mb_off b (mb_put_es es insz n x) tbp 16.
  Hypothesis B2 : mb_off b (mb_put_es es insz n x) tep 16.
  Hypothesis B3 : mb_off b (mb_put_es es insz n x) srp 40.
  Hypothesis B4 : mb_off b (mb_put_es es insz n x) cbp 16.
  Hypothesis ST : stk asegs m0 lo (bv_unsigned sp).
  Hypothesis LO : lo + MB_BCOPY_STACK <= bv_unsigned sp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis RA : bv_unsigned ra mod 2 = 0.
  Hypothesis MI : mem_inv asegs m0.
  Hypothesis SPAL : bv_unsigned sp mod 16 = 0.
  Hypothesis AC : ACONST m0.
  Hypothesis SK : stack0 m0 lo shi.
  Hypothesis SHI : bv_unsigned sp <= shi.
  Hypothesis TAL : tbp mod 8 = 0.
  Hypothesis TACC : accessible m0 tbp 16.
  Hypothesis EAL : tep mod 8 = 0.
  Hypothesis EACC : accessible m0 tep 16.
  Hypothesis SAL : srp mod 8 = 0.
  Hypothesis SACC : accessible m0 srp 40.
  Hypothesis CAL : cbp mod 8 = 0.
  Hypothesis CACC : accessible m0 cbp 16.
  Hypothesis SCA : accessible m0 src n.
  Hypothesis SCV : shvis m0 src (src + n).
  Hypothesis SCI : in_app_mem src (src + n).
  Hypothesis SV1 : shvis m0 (fst (mb_b1 b es insz n x)) (fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x)).
  Hypothesis SV2 : shvis m0 (fst (mb_b2 b es insz n x)) (fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x)).
