  (* [comment removed for export] *)
  Lemma bcopy_body : forall (t0 t1 t2 a0 a1 a5 a7 t3 t4 t5 t6 : word),
    evt asegs (bcopy_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc tbp tep srp cbp src b es insz n x lo shi bs m0)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (wz tbp) (wz tep) (wz cbp) a5 (Z_to_bv 64 (2^64 - 1)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_A_BUFFER_COPY_MB) fc None m0 (seg_rom asegs)).
  Proof.
    intros. pose proof (mb_ok_bounds _ _ OK) as [IB CB0].
    destruct (mb_need es insz n) eqn:ND.
    - destruct (mb_full es insz) eqn:FU.
      + (* [comment removed for export] *)
        destruct (mb_shape_full b es insz n x OK N1 FU) as (_ & EES & EINS & _ & EMO & EOP & EOE & NG & I0).
        eapply (bc_one es x (mb_grow es insz n) 0);
          [ exact EES | exact EMO | exact EOP | rewrite EOE; clear; lia | clear; lia | clear - NG; lia
          | unfold mb_b1; rewrite ND, FU; f_equal; clear; lia
          | unfold mb_b2, mb_b1; rewrite ND, FU; cbn [andb negb]; f_equal; clear; lia ].
      + (* [comment removed for export] *)
        destruct (mb_shape_part b es insz n x OK N1 FU ND) as (P & xl & sl & EesP & EES & _ & EMO & ELA & ELS & ECI & EOP & OP1 & OPS & NGT & EOE & OEG & CP0).
        eapply (bc_two P xl sl (mb_grow es insz n) (insz - mb_cap P) (insz + n - (mb_cap P + sl)));
          [ rewrite EES, EesP; reflexivity | exact EMO | exact EOP | exact EOE | exact OP1 | exact OPS
          | clear - NGT; lia | exact OEG | clear; lia
          | unfold mb_b1; rewrite ND, FU, ELA, EOP, EesP, mb_cap_snoc; f_equal; clear; lia
          | unfold mb_b2; rewrite ND, FU; cbn [andb negb]; rewrite EesP, mb_cap_snoc; f_equal; clear; lia ].
    - (* [comment removed for export] *)
      destruct (mb_shape_noneed b es insz n OK N1 ND) as (P & xl & sl & EesP & FU & _ & _ & ELA & ELS & ECI & EOP & OP1 & OPN & EOE & CP0).
      eapply (bc_one P xl sl (insz - mb_cap P));
        [ unfold mb_put_es; rewrite ND; exact EesP | unfold mb_mid_out; rewrite FU; exact ELA | exact EOP | exact EOE
        | clear - OP1; lia | exact OPN
        | unfold mb_b1; rewrite ND, ELA, EOP; reflexivity
        | unfold mb_b2, mb_b1; rewrite ND; cbn [andb]; rewrite ELA, EOP; reflexivity ].
  Qed.

End BC.

Lemma bcopy_spec : asan_memcpy_stmt -> bcopy_stmt.
Proof.
  intros MEMCPY. intros until m.
  intros MID OK N1 NB TB TE SR CBC SRC LBS SLO A1 A2 A3 A4 B0 B1 B2 B3 B4 ST LO CEIL RA MI SPAL AC SK SHI TAL TACC EAL EACC SAL SACC CAL CACC SCA SCV SCI SV1 SV2.
  eapply bcopy_body; eassumption.
Qed.

End HCW.
